<script lang="ts">
 import {createEventDispatcher} from 'svelte';
 export let panels:any[]=[];export let activeKey='';export let minimized=false;export let companyId:string;export let actorId:string;export let accessSignal:AbortSignal;
 const dispatch=createEventDispatcher();let expanded=false,dirty:Record<string,boolean>={};
 function close(panel:any){if(dirty[panel.key]&&!confirm('Discard unsaved changes in this panel?'))return;dispatch('close',{key:panel.key});}
</script>
{#if panels.length}<section class="panel-workspace" class:expanded class:minimized aria-label="Workspace panels"><header><div class="tabs" role="tablist" aria-label="Open panels">{#each panels as panel(panel.key)}<button role="tab" aria-selected={activeKey===panel.key} class:active={activeKey===panel.key} on:click={()=>dispatch('select',{key:panel.key})}>{panel.title}{dirty[panel.key]?' •':''}</button>{/each}</div><div class="actions"><button aria-label="Minimize panels" on:click={()=>dispatch('minimize')}>−</button><button aria-label={expanded?'Exit expanded panel':'Expand panel'} on:click={()=>expanded=!expanded}>{expanded?'↙':'↗'}</button>{#if panels.find(panel=>panel.key===activeKey)}<button aria-label="Close selected panel" on:click={()=>close(panels.find(panel=>panel.key===activeKey))}>×</button>{/if}</div></header><div class="surfaces">{#each panels as panel(panel.key)}<div class="surface" class:hidden={activeKey!==panel.key} role="tabpanel" aria-hidden={activeKey!==panel.key}><svelte:component this={panel.component} {...panel.props} {companyId} {actorId} {accessSignal} on:dirty={event=>dirty={...dirty,[panel.key]:event.detail.dirty}} on:close={()=>dispatch('close',{key:panel.key})} on:revoked={()=>dispatch('close',{key:panel.key})} on:denied={event=>dispatch('denied',event.detail||{status:403})}/></div>{/each}</div></section>{/if}
<style>.panel-workspace{width:clamp(380px,46vw,820px);height:100dvh;flex:none;border-left:1px solid #e6ebf4;background:#fff;display:flex;flex-direction:column;min-width:0;color:#17243f}.panel-workspace.expanded{position:fixed;inset:0;width:100%;z-index:80}header{height:48px;flex:none;display:flex;align-items:center;border-bottom:1px solid #e6ebf4;padding:0 10px;gap:10px}.tabs{display:flex;gap:5px;overflow:auto;flex:1;min-width:0}.tabs button{white-space:nowrap;padding:7px 10px;border:1px solid transparent;border-radius:7px;font-size:11px;color:#71809a;background:none}.tabs button.active{background:#eef3ff;border-color:#dfe8fd;color:#3466f6}.actions{display:flex;gap:2px}.actions button{border:0;background:none;padding:5px 8px;color:#71809a;font-size:17px}.surfaces{flex:1;min-height:0;position:relative}.surface{height:100%;overflow:auto}.surface.hidden{display:none}.surface :global(.file-pane),.surface :global(.browser),.surface :global(.company-computer){width:100%!important;height:100%!important;min-width:0;border-left:0!important;position:static!important}.surface :global(.file-pane header){height:56px}button{font:inherit;cursor:pointer}button:focus-visible{outline:2px solid #9cb7ff;outline-offset:2px}@media(max-width:800px){.panel-workspace{position:fixed;inset:0;width:100%;z-index:60}}
.panel-workspace.minimized{display:none}
</style>
